-- Lookup lists for the cross-file rules (built from this run's base files)
CREATE OR REPLACE VIEW ref_orders AS
            SELECT order_id, order_amount FROM stg_orders_std
            WHERE order_id IS NOT NULL
            QUALIFY row_number() OVER (PARTITION BY order_id ORDER BY _row) = 1;

CREATE OR REPLACE VIEW ref_payments AS
            SELECT order_id, payment_status FROM stg_payments_std WHERE order_id IS NOT NULL;

CREATE OR REPLACE VIEW ref_customers AS
            SELECT DISTINCT customer_id FROM stg_customers_std WHERE customer_id IS NOT NULL;

CREATE OR REPLACE VIEW ref_products AS
            SELECT DISTINCT product_id FROM stg_products_std WHERE product_id IS NOT NULL;

CREATE OR REPLACE VIEW ref_stores AS
            SELECT DISTINCT store_id FROM stg_stores_std WHERE store_id IS NOT NULL;

CREATE OR REPLACE VIEW ref_product_mrp AS
            SELECT product_id, mrp FROM stg_products_std
            WHERE product_id IS NOT NULL
            QUALIFY row_number() OVER (PARTITION BY product_id ORDER BY
                    CASE WHEN product_name LIKE '%(old)' THEN 1 ELSE 0 END, _row) = 1
                AND mrp > 0;
